------------------------------------------------------------------
-- АНТИ-СКРЫТИЕ v6.7, часть 1: поколение запуска и общее состояние.
-- Каждый запуск скрипта увеличивает счётчик в getgenv()/_G —
-- сторожевые циклы предыдущего запуска видят смену поколения
-- и гаснут, чтобы не пересоздавать старое окно поверх нового.
------------------------------------------------------------------
local GEN_KEY = "AUTOPIANO_ACTIVE_GEN"
local function genGet()
    if type(getgenv) == "function" then
        local ok, v = pcall(function() return getgenv()[GEN_KEY] end)
        if ok then return v end
    end
    return rawget(_G, GEN_KEY)
end
local function genSet(v)
    if type(getgenv) == "function" then pcall(function() getgenv()[GEN_KEY] = v end) end
    rawset(_G, GEN_KEY, v)
end
genSet((tonumber(genGet()) or 0) + 1)
local MY_GEN = genGet()

-- Общее состояние защиты: его видят и сборщик GUI, и сторож.
