    cleanup    = nil,   -- остановка воспроизведения при пересборке
}

-- Если на твоём экзекуторе GUI в CoreGui/gethui не отображается или
-- не нажимается (бывает на старых мобильных) — поставь true, и GUI
-- вернётся в PlayerGui (защиту тогда обеспечивает сторож внизу).
local FORCE_PLAYERGUI = false

------------------------------------------------------------------
-- АНТИ-СКРЫТИЕ, часть 2: чистим прошлые запуски во ВСЕХ контейнерах
-- (PlayerGui + CoreGui + gethui), а не только в PlayerGui.
------------------------------------------------------------------
do
    local function killOld(container)
        if type(container) ~= "Instance" then return end
        local old = container:FindFirstChild("AutoPianoPlayer")
        if old then pcall(function() old:Destroy() end) end
    end
    killOld(playerGui)
    pcall(function() killOld(game:GetService("CoreGui")) end)
    if type(gethui) == "function" then
        pcall(function() killOld(gethui()) end)
    end
end

