local function corner(p, r)
    local c = Instance.new("UICorner"); c.CornerRadius = r or CR; c.Parent = p; return c
end
local function stroke(p, col, th)
    local s = Instance.new("UIStroke")
    s.Color = col or BORDER; s.Thickness = th or 1
    s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border; s.Parent = p; return s
end
local function tw(obj, props, t)
    TweenService:Create(obj, TweenInfo.new(t or 0.15, Enum.EasingStyle.Quad), props):Play()
end

------------------------------------------------------------------
-- АНТИ-СКРЫТИЕ, часть 3: где GUI будет жить.
--   1) gethui()  — скрытый контейнер экзекутора: игровые скрипты его
--                  вообще не видят, удалить/скрыть не смогут;
--   2) CoreGui   — игре запрещено писать и удалять;
--   3) PlayerGui — фолбэк: там GUI защищает сторожевой цикл.
------------------------------------------------------------------
local function resolveGuiHome()
    local function writable(inst)
        if type(inst) ~= "Instance" then return false end
        return pcall(function()
            local probe = Instance.new("Folder")
            probe.Name   = "_AP_write_probe"
            probe.Parent = inst
            probe:Destroy()
        end)
    end
    if not FORCE_PLAYERGUI then
        if type(gethui) == "function" then
            local ok, hui = pcall(gethui)
            if ok and writable(hui) then return hui, "gethui" end
        end
        if type(get_coregui) == "function" then
            local ok, cg = pcall(get_coregui)
            if ok and writable(cg) then return cg, "CoreGui" end
        end
        do
            local ok, cg = pcall(function() return game:GetService("CoreGui") end)
            if ok and writable(cg) then return cg, "CoreGui" end
        end
    end
    return playerGui, "PlayerGui"
end

local GUI_HOME, GUI_HOME_NAME = resolveGuiHome()

