local SPEED_MIN, SPEED_MAX = 0.5, 10.0
local SPEED = 1.0
local function setSpeed(v)
    SPEED = math.clamp(v, SPEED_MIN, SPEED_MAX)
    local alpha = (SPEED - SPEED_MIN) / (SPEED_MAX - SPEED_MIN)
    speedFill.Size      = UDim2.new(alpha, 0, 1, 0)
    speedThumb.Position = UDim2.new(alpha, 0, 0.5, 0)
    speedVal.Text       = (SPEED >= 9.995) and string.format("%.1fx", SPEED)
                          or string.format("%.2fx", SPEED)
    if math.abs(SPEED - 1.0) < 0.01 then
        speedVal.TextColor3 = TEXT
    else
        speedVal.TextColor3 = ACCENT
    end
end

local draggingSlider = false
local function sliderFromAbs(absX)
    local rel = (absX - speedTrack.AbsolutePosition.X) / math.max(speedTrack.AbsoluteSize.X, 1)
    setSpeed(SPEED_MIN + math.clamp(rel, 0, 1) * (SPEED_MAX - SPEED_MIN))
end
local function beginSliderDrag(input)
    draggingSlider = true
    sliderFromAbs(input.Position.X)
    input.Changed:Connect(function()
        if input.UserInputState == Enum.UserInputState.End then draggingSlider = false end
    end)
end
speedThumb.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        beginSliderDrag(input)
    end
end)
speedTrack.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        beginSliderDrag(input)
    end
end)
UserInputService.InputChanged:Connect(function(input)
    if not draggingSlider then return end
    if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
        sliderFromAbs(input.Position.X)
    end
end)
setSpeed(1.0)

