-- запрос перемотки: UI пишет абсолютную позицию (вирт. секунды),
-- цикл воспроизведения забирает её на ближайшем тике ожидания
local function requestSeek(absPos)
    local st = playState
    if st.entry and st.dur > 0 then
        st.entry.seekReq = math.clamp(absPos, 0, st.dur)
    end
end

local function seekFromAbs(absX)
    local rel = (absX - seekTrack.AbsolutePosition.X)
        / math.max(seekTrack.AbsoluteSize.X, 1)
    requestSeek(math.clamp(rel, 0, 1) * playState.dur)
end

local function nudgeSeek(delta)
    requestSeek(playState.pos + delta)
end

local draggingSeek = false
local function beginSeekDrag(input)
    if not (playState.entry and playState.dur > 0) then return end
    draggingSeek = true
    seekFromAbs(input.Position.X)
    input.Changed:Connect(function()
        if input.UserInputState == Enum.UserInputState.End then
            draggingSeek = false
        end
    end)
end
seekThumb.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
        beginSeekDrag(input)
    end
end)
seekTrack.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
        beginSeekDrag(input)
    end
end)
UserInputService.InputChanged:Connect(function(input)
    if not draggingSeek then return end
    if input.UserInputType == Enum.UserInputType.MouseMovement
        or input.UserInputType == Enum.UserInputType.Touch then
        seekFromAbs(input.Position.X)
    end
end)
seekBack.MouseButton1Click:Connect(function() nudgeSeek(-10) end)
seekFwd.MouseButton1Click:Connect(function() nudgeSeek(10) end)

------------------------------------------------------------------
-- ВВОД: VirtualInputManager -> keypress/keyrelease (VK-коды)
------------------------------------------------------------------
local VK = {
    Backspace=0x08,Tab=0x09,Return=0x0D,LeftShift=0xA0,RightShift=0xA1,
    LeftControl=0xA2,RightControl=0xA3,LeftAlt=0xA4,RightAlt=0xA5,
    Pause=0x13,CapsLock=0x14,Escape=0x1B,Space=0x20,PageUp=0x21,
    PageDown=0x22,End=0x23,Home=0x24,Left=0x25,Up=0x26,Right=0x27,
    Down=0x28,Insert=0x2D,Delete=0x2E,Semicolon=0xBA,Equals=0xBB,
    Comma=0xBC,Minus=0xBD,Period=0xBE,Slash=0xBF,Backquote=0xC0,
    LeftBracket=0xDB,BackSlash=0xDC,RightBracket=0xDD,Quote=0xDE,
}
VK.Zero=0x30 VK.One=0x31 VK.Two=0x32 VK.Three=0x33 VK.Four=0x34
VK.Five=0x35 VK.Six=0x36 VK.Seven=0x37 VK.Eight=0x38 VK.Nine=0x39
for i=1,12 do VK["F"..i]=0x6F+i end
for c=string.byte("A"),string.byte("Z") do VK[string.char(c)]=c end

local function getGlobalFn(name)
    if type(getgenv) == "function" then
        local ok, v = pcall(function() return getgenv()[name] end)
        if ok and type(v) == "function" then return v end
    end
    local v = rawget(_G, name)
    if type(v) == "function" then return v end
    return nil
end

local vimOk, VIM = pcall(function() return game:GetService("VirtualInputManager") end)
if not (vimOk and VIM and VIM.SendKeyEvent) then vimOk = false; VIM = nil end

local FN_keypress   = getGlobalFn("keypress")
local FN_keyrelease = getGlobalFn("keyrelease")

local INPUT_NAME
if vimOk then
    INPUT_NAME = "VirtualInputManager"
elseif FN_keypress or FN_keyrelease then
    INPUT_NAME = "keypress/keyrelease"
else
    INPUT_NAME = "NONE"
end

local INPUT_MODES = {"AUTO", "VIM", "KEYS"}
local INPUT_MODE  = 1

local function refreshModeBtn()
    modeBtn.Text = "in: " .. INPUT_MODES[INPUT_MODE]
    if INPUT_NAME == "NONE" then
        modeBtn.Text = modeBtn.Text .. " (no API!)"
        modeBtn.TextColor3 = Color3.fromRGB(255, 120, 120)
    else
        modeBtn.TextColor3 = SUBTEXT
    end
end
modeBtn.MouseButton1Click:Connect(function()
    INPUT_MODE = INPUT_MODE % #INPUT_MODES + 1
    refreshModeBtn()
end)
refreshModeBtn()

if INPUT_NAME == "NONE" then
    statusLabel.TextColor3 = Color3.fromRGB(255, 120, 120)
end

local function emitKey(isDown, keyCode)
    local mode = INPUT_MODES[INPUT_MODE]
    if mode ~= "KEYS" and vimOk then
        local ok = pcall(function() VIM:SendKeyEvent(isDown, keyCode, false, game) end)
        if ok then return true end
    end
    if mode ~= "VIM" then
        local n = VK[keyCode.Name]
        if n then
            if isDown and FN_keypress then
                if pcall(FN_keypress, n) then return true end
            end
            if (not isDown) and FN_keyrelease then
                if pcall(FN_keyrelease, n) then return true end
            end
        end
    end
    return false
end

------------------------------------------------------------------
-- ПАРСЕР v6: посимвольная токенизация
-- Понимает склеенные листы вида "[6eu]-u-u-t- [5rt]" (practice-data),
-- "----", "—", сустейн "_", аккорды [..] c фильтрацией мусора.
-- Модель таймингов сайта: шаг = 1/8 = 60/BPM/2; hold=(1+carry)*шаг*0.92.
-- Защиты: ролл в границах шага, грейс-ноты 28мс, каскад LeftShift,
-- слияние рестрайков <7мс, глобальная нормализация LeftShift.
------------------------------------------------------------------
local DIGIT_NAMES = {"Zero","One","Two","Three","Four","Five","Six","Seven","Eight","Nine"}
local SYMBOL_MAP = {
    ["!"] = {key="One",   shift=true},
    ["@"] = {key="Two",   shift=true},
    ["#"] = {key="Three", shift=true},
    ["$"] = {key="Four",  shift=true},
    ["%"] = {key="Five",  shift=true},
    ["^"] = {key="Six",   shift=true},
    ["&"] = {key="Seven", shift=true},
    ["*"] = {key="Eight", shift=true},
    ["("] = {key="Nine",  shift=true},
    [")"] = {key="Zero",  shift=true},
}

-- раскладка сайта: токен -> midi (C2..C7 по порядку)
local TOK_MIDI = {}
do
    local whites = "1234567890qwertyuiopasdfghjklzxcvbnm"
    local blacks = "!@$%^*(QWETYIOPSDGHJLZCVB"
    local sharpAt = {[1]=true, [3]=true, [6]=true, [8]=true, [10]=true}
    local wi, bi = 1, 1
    for midi = 36, 96 do
        if sharpAt[(midi % 12)] then
            TOK_MIDI[blacks:sub(bi, bi)] = midi; bi = bi + 1
        else
            TOK_MIDI[whites:sub(wi, wi)] = midi; wi = wi + 1
        end
    end
end

local function tokenKey(tok)
    if TOK_MIDI[tok] == nil then return nil, false, nil end
    local m = SYMBOL_MAP[tok]
    if m then return m.key, m.shift, TOK_MIDI[tok] end
    local b = tok:byte()
    if b >= 48 and b <= 57 then return DIGIT_NAMES[b - 47], false, TOK_MIDI[tok] end
    if b >= 65 and b <= 90 then return tok, true, TOK_MIDI[tok] end
    if b >= 97 and b <= 122 then return string.upper(tok), false, TOK_MIDI[tok] end
    return nil, false, nil
end

local function parseNoteString(noteStr, startT, stepSec)
    local events = {}
    local t = startT or START_AT
    stepSec = stepSec or 0.25

    -- 1) посимвольная токенизация (склеенные аккорды/ноты/серии пауз)
    local toks = {}
    local i, n = 1, #noteStr
    local chord = nil
    while i <= n do
        local ch = noteStr:sub(i, i)
        if ch == "[" then
            chord = {}
        elseif ch == "]" then
            if chord then
                local keep = {}
                for j = 1, #chord do
                    if TOK_MIDI[chord[j]] then table.insert(keep, chord[j]) end
                end
                if #keep > 0 then table.insert(toks, {kind="chord", list=keep}) end
                chord = nil
            end
        elseif chord then
            table.insert(chord, ch)
        elseif ch == "-" then
            table.insert(toks, {kind="pause", steps=1, sustain=false})
        elseif ch == "_" then
            table.insert(toks, {kind="pause", steps=1, sustain=true})
        elseif ch == "\226\128\148" then -- em-dash "—"
            table.insert(toks, {kind="pause", steps=2, sustain=false})
            i = i + 2
        elseif ch == "|" or ch == " " or ch == "\n" or ch == "\r" or ch == "\t" then
            -- разделители: 0 шагов
        elseif TOK_MIDI[ch] then
            table.insert(toks, {kind="note", list={ch}})
        end
        i = i + 1
    end

    -- 2) расписание с hold и сустейн-переносом
    local rollStagger = math.min(0.032, stepSec * 0.18)
    local lsDown = false
    for idx = 1, #toks do
        local ev = toks[idx]
        if ev.kind == "note" or ev.kind == "chord" then
            local carry = 0
            local k = idx + 1
            while k <= #toks do
                local nx = toks[k]
                if nx.kind == "note" or nx.kind == "chord" then break end
                local isSus = (nx.kind == "pause" and nx.sustain)
                if not isSus then break end
                carry = carry + (nx.steps or 0)
                if carry >= 8 then break end
                k = k + 1
            end
            local hold = math.clamp((1 + carry) * stepSec * 0.92, 0.09, 1.8)

            local keys = {}
            for _, tk in ipairs(ev.list) do
                local kn, sh, mi = tokenKey(tk)
                if kn then table.insert(keys, {key = kn, shift = sh, midi = mi or 60}) end
            end
            table.sort(keys, function(a, b) return a.midi < b.midi end)

            local clash = false
            for j = 1, #keys - 1 do
                if keys[j + 1].midi - keys[j].midi <= 1 then clash = true end
            end
            local seen, grace = {}, {}
            for j = 1, #keys do
                grace[j] = seen[keys[j].key] == true
                seen[keys[j].key] = true
            end
            local stagger = clash and rollStagger or 0.004
            if #keys > 1 then
                local cap = math.max(0.002, (stepSec - 0.03) / (#keys - 1))
                if stagger > cap then stagger = cap end
            end

            local kds = {}
            for j = 1, #keys do kds[j] = t + (j - 1) * stagger end
            local lsDownT, lastLsUp = nil, nil
            for j = 1, #keys do
                local kk     = keys[j]
                local kd     = kds[j]
                local holdI  = grace[j] and 0.028 or math.max(0.09, hold - (j - 1) * stagger)
                if kk.shift then
                    if not lsDown then
                        local d = kd - 0.004
                        if lastLsUp and d < lastLsUp + 0.001 then
                            local delta = lastLsUp + 0.001 - d
                            for q = j, #keys do kds[q] = kds[q] + delta end
                            kd = kds[j]; d = kd - 0.004
                        end
                        table.insert(events, {t = d, key = "LeftShift", state = "down"})
                        lsDown = true; lsDownT = d
                    end
                    table.insert(events, {t = kd, key = kk.key, state = "down"})
                    local nxt = keys[j + 1]
                    if not (nxt and nxt.shift) then
                        local u = kd + 0.003
                        table.insert(events, {t = u, key = "LeftShift", state = "up"})
                        lsDown = false; lastLsUp = u
                        if nxt and kds[j + 1] < u + 0.001 then
                            local delta = u + 0.001 - kds[j + 1]
                            for q = j + 1, #keys do kds[q] = kds[q] + delta end
                        end
                    end
                else
                    if lsDown then
                        local u = kd - 0.005
                        if u < lsDownT + 0.001 then
                            local delta = lsDownT + 0.001 - u
                            for q = j, #keys do kds[q] = kds[q] + delta end
                            kd = kds[j]; u = kd - 0.005
                        end
                        table.insert(events, {t = u, key = "LeftShift", state = "up"})
                        lsDown = false; lastLsUp = u
                    end
                    table.insert(events, {t = kd, key = kk.key, state = "down"})
                end
                table.insert(events, {t = kd + holdI, key = kk.key, state = "up"})
            end
            t = t + stepSec
        elseif ev.kind == "pause" then
            t = t + ev.steps * stepSec
        end
    end
    if lsDown then
        table.insert(events, {t = t, key = "LeftShift", state = "up"})
    end

    -- 3) пост-фикк: рестрайки зажатой клавиши (двухпроходный FIFO)
    table.sort(events, function(a, b) return a.t < b.t end)

    local queue, pairIdx = {}, {}
    for j = 1, #events do
        local e = events[j]
        if e.key ~= "LeftShift" then
            if e.state == "down" then
                local q = queue[e.key]
                if not q then q = {} queue[e.key] = q end
                table.insert(q, j)
            else
                local q = queue[e.key]
                if q and #q > 0 then
                    pairIdx[table.remove(q, 1)] = j
                end
            end
        end
    end

    local out, held, drop = {}, {}, {}
    local lsDownT = nil
    for j = 1, #events do
        local e = events[j]
        if e.key == "LeftShift" then
            if e.state == "down" then lsDownT = e.t else lsDownT = nil end
            table.insert(out, e)
        elseif e.state == "down" then
            local jPrev = held[e.key]
            if jPrev then
                if pairIdx[jPrev] then drop[pairIdx[jPrev]] = true end
                local upT = e.t - 0.015
                if lsDownT and (e.t - lsDownT) < 0.01 then
                    upT = math.min(upT, lsDownT - 0.001)
                end
                if upT <= events[jPrev].t then upT = events[jPrev].t + 0.006 end
                if upT >= e.t then
                    drop[j] = true
                else
                    table.insert(out, {t = upT, key = e.key, state = "up"})
                end
            end
            held[e.key] = j
            if not drop[j] then table.insert(out, e) end
        else
            local jPrev = held[e.key]
            if jPrev and pairIdx[jPrev] == j then held[e.key] = nil end
            if not drop[j] then table.insert(out, e) end
        end
    end
    table.sort(out, function(a, b) return a.t < b.t end)

    -- 4) строгая нормализация LeftShift по всей песне
    local lsHeld = false
    local out2 = {}
    for j = 1, #out do
        local e = out[j]
        if e.key == "LeftShift" then
            if e.state == "down" then
                if not lsHeld then
                    lsHeld = true
                    table.insert(out2, e)
                end
            else
                if lsHeld then
                    lsHeld = false
                    table.insert(out2, e)
                end
            end
        else
            table.insert(out2, e)
        end
    end
    table.sort(out2, function(a, b) return a.t < b.t end)
    return out2
end

-- кэш распарсенных треков (лимит — экономия памяти)
local EV_CACHE, CACHE_ORDER, CACHE_MAX = {}, {}, 14
local function getEvents(track)
    local c = EV_CACHE[track]
    if c then return c end
    local bpm = track.bpm or 120
    local gap = math.clamp(60 / (bpm * 2) * TEMPO_SCALE, 0.12, 0.5)
    local evs
    if track.kind == "events" then
        evs = track.events
    else
        evs = parseNoteString(track.notes, START_AT, gap)
    end
    EV_CACHE[track] = evs
    table.insert(CACHE_ORDER, track)
    if #CACHE_ORDER > CACHE_MAX then
        local old = table.remove(CACHE_ORDER, 1)
        if old ~= track then EV_CACHE[old] = nil end
    end
    return evs
end

local function waitUntil(target, stillValid)
    while true do
        local d = target - os.clock()
        if d <= 0.004 then break end
        task.wait(math.min(d - 0.004, 0.25))
        if stillValid and not stillValid() then return false end
    end
    local guard = 0
    while os.clock() < target and guard < 60000 do
        guard = guard + 1
    end
    return true
end

