-- ПЛЕЕР
------------------------------------------------------------------
local isPlaying    = false
local currentEntry = nil

local function fmtDur(sec)
    sec = math.max(0, math.floor(sec))
    return string.format("%d:%02d", sec // 60, sec % 60)
end

-- ПЕРЕМОТКА: полоса прогресса и таймер обновляются 10 раз в секунду
task.spawn(function()
    while true do
        task.wait(0.1)
        local st = playState
        if st.entry and isPlaying and currentEntry == st.entry and st.dur > 0 then
            local alpha = math.clamp(st.pos / st.dur, 0, 1)
            seekFill.Size      = UDim2.new(alpha, 0, 1, 0)
            seekThumb.Position = UDim2.new(alpha, 0, 0.5, 0)
            seekTime.Text      = fmtDur(st.pos) .. " / " .. fmtDur(st.dur)
        end
    end
end)

------------------------------------------------------------------
-- ЛАЙКИ (плейлист Likes): звёздочка у каждой песни.
-- Понравившиеся треки собираются в разделе "★ Likes" и сохраняются
-- между запусками: файл экзекутора (writefile) + getgenv как запасной.
------------------------------------------------------------------
local LIKE_SET_KEY = "AUTOPIANO_LIKES_V1"
local LIKE_FILE    = "autopiano_likes.json"
local likes = {}
local onLikeToggled  -- назначается ниже, после создания чипов и списка

local function trackKey(track)
    return tostring(track.name) .. "|" .. tostring(track.artist) .. "|"
        .. tostring(track.bpm) .. "|" .. tostring(track.st)
end

local function saveLikes()
    local arr = {}
    for k in pairs(likes) do table.insert(arr, k) end
    if type(writefile) == "function" then
        pcall(function() writefile(LIKE_FILE, HttpService:JSONEncode(arr)) end)
    end
    pcall(function()
        local t = {}
        for k in pairs(likes) do t[k] = true end
        getgenv()[LIKE_SET_KEY] = t
    end)
end

do -- загрузка: сначала файл экзекутора, затем getgenv()
    local loaded = false
    if type(readfile) == "function" and type(isfile) == "function" then
        pcall(function()
            if isfile(LIKE_FILE) then
                local ok, data = pcall(function()
                    return HttpService:JSONDecode(readfile(LIKE_FILE))
                end)
                if ok and type(data) == "table" then
                    for _, k in ipairs(data) do likes[k] = true end
                    loaded = true
                end
            end
        end)
    end
    if not loaded then
        pcall(function()
            local saved = getgenv()[LIKE_SET_KEY]
            if type(saved) == "table" then
                for k in pairs(saved) do likes[k] = true end
            end
        end)
    end
end

local CAT_COLORS = {
    Phonk     = Color3.fromRGB(167, 87, 255),
    Electronic= Color3.fromRGB(96, 165, 250),
    Game      = Color3.fromRGB(52, 199, 89),
    Pop       = Color3.fromRGB(255, 105, 180),
    Anime     = Color3.fromRGB(255, 140, 66),
    Classical = Color3.fromRGB(214, 178, 106),
    Movie     = Color3.fromRGB(120, 190, 255),
    Rock      = Color3.fromRGB(255, 99, 99),
    ["Hip-Hop"] = Color3.fromRGB(255, 176, 32),
    ["K-Pop"] = Color3.fromRGB(200, 120, 255),
    FNF       = Color3.fromRGB(120, 220, 120),
    Meme      = Color3.fromRGB(255, 220, 90),
    Ringtone  = Color3.fromRGB(130, 255, 150),
    Traditional = Color3.fromRGB(140, 200, 160),
    Vocaloid  = Color3.fromRGB(90, 220, 220),
    Jazz      = Color3.fromRGB(210, 140, 255),
    Repo      = Color3.fromRGB(130, 130, 145),
    Other     = Color3.fromRGB(150, 152, 168),
}

local function makeRow(orderIdx, track, shownIdx)
    local row = Instance.new("Frame")
    row.Size = UDim2.new(1, 0, 0, 36)
    row.LayoutOrder = shownIdx
    row.BackgroundColor3 = SURF2
    row.BorderSizePixel = 0
    row.Parent = listContainer
    corner(row, UDim.new(0, 7))

    local catCol = CAT_COLORS[track.cat] or CAT_COLORS.Other

    -- цветная полоска категории
    local bar = Instance.new("Frame")
    bar.Size = UDim2.new(0, 3, 1, -10)
    bar.Position = UDim2.new(0, 3, 0.5, -13)
    bar.BackgroundColor3 = catCol
    bar.BorderSizePixel = 0
    bar.Parent = row
    corner(bar, UDim.new(1, 2))

    local lbl = Instance.new("TextLabel")
    lbl.Size = UDim2.new(1, -200, 0, 17)
    lbl.Position = UDim2.new(0, 38, 0, 2)
    lbl.BackgroundTransparency = 1
    lbl.Text = track.name
    lbl.Font = Enum.Font.GothamSemibold
    lbl.TextSize = 12
    lbl.TextColor3 = TEXT
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    lbl.TextTruncate = Enum.TextTruncate.AtEnd
    lbl.Parent = row

    local sub = Instance.new("TextLabel")
    sub.Size = UDim2.new(1, -200, 0, 13)
    sub.Position = UDim2.new(0, 38, 1, -15)
    sub.BackgroundTransparency = 1
    local subBits = {}
    if track.artist and track.artist ~= "" and track.artist ~= "Unknown" then
        table.insert(subBits, track.artist)
    end
    table.insert(subBits, (track.bpm or 120) .. " BPM")
    if track.st and track.bpm then
        table.insert(subBits, fmtDur(track.st * 60 / (track.bpm * 2)))
    end
    table.insert(subBits, track.lvl or "Hard")
    sub.Text = table.concat(subBits, " • ")
    sub.Font = Enum.Font.Gotham
    sub.TextSize = 10
    sub.TextColor3 = SUBTEXT
    sub.TextXAlignment = Enum.TextXAlignment.Left
    sub.TextTruncate = Enum.TextTruncate.AtEnd
    sub.Parent = row

    local catTag = Instance.new("TextLabel")
    catTag.Size = UDim2.new(0, 62, 0, 16)
    catTag.Position = UDim2.new(1, -92, 0.5, -8)
    catTag.BackgroundTransparency = 1
    catTag.Text = track.cat or "Other"
    catTag.Font = Enum.Font.GothamSemibold
    catTag.TextSize = 9
    catTag.TextColor3 = catCol
    catTag.TextXAlignment = Enum.TextXAlignment.Right
    catTag.TextTruncate = Enum.TextTruncate.AtEnd
    catTag.Parent = row

    local btn = Instance.new("TextButton")
    btn.Size = UDim2.new(0, 66, 0, 24)
    btn.Position = UDim2.new(1, -70, 0.5, -12)
    btn.Text = "▶"
    btn.Font = Enum.Font.GothamBold
    btn.TextSize = 13
    btn.TextColor3 = Color3.fromRGB(255, 255, 255)
    btn.BackgroundColor3 = Color3.fromRGB(58, 110, 190)
    btn.BorderSizePixel = 0
    btn.Parent = row
    corner(btn, UDim.new(0, 6))

    -- звезда лайка слева от названия
    local star = Instance.new("TextButton")
    star.Size = UDim2.new(0, 24, 0, 24)
    star.Position = UDim2.new(0, 11, 0.5, -12)
    star.BackgroundTransparency = 1
    star.Font = Enum.Font.GothamSemibold
    star.TextSize = 16
    star.Parent = row

    local function refreshStar()
        local liked = likes[trackKey(track)] == true
        star.Text = liked and "★" or "☆"
        star.TextColor3 = liked and AMBER or SUBTEXT
    end

    local entry = {row=row, btn=btn, track=track, playing=false}
    entry.refreshStar = refreshStar
    refreshStar()

    local function setEntryState(playing)
        entry.playing = playing
        if playing then
            tw(btn, {BackgroundColor3 = RED, TextColor3 = Color3.fromRGB(255,255,255)}, 0.12)
            btn.Text = "■"
            row.BackgroundColor3 = Color3.fromRGB(52, 36, 46)
        else
            tw(btn, {BackgroundColor3 = Color3.fromRGB(58, 110, 190)}, 0.12)
            btn.Text = "▶"
            row.BackgroundColor3 = SURF2
        end
    end

    entry.setEntryState = setEntryState
    entry.stopEntry = function(reason)
        isPlaying = false; currentEntry = nil
        setEntryState(false)
        statusLabel.Text = reason or "Stopped"
    end

    entry.startEntry = function()
        if entry.parsing or entry.playing then return end -- guard от двойного клика
        if isPlaying and currentEntry and currentEntry ~= entry then
            isPlaying = false
            currentEntry.playing = false
            currentEntry.setEntryState(false)
        end
        entry.parsing = true
        statusLabel.Text = "Parsing..."
        task.defer(function()
            local okEvs, evs = pcall(getEvents, track)
            entry.parsing = false
            if not okEvs or type(evs) ~= "table" or #evs == 0 then
                statusLabel.Text = "No events in " .. tostring(track.name)
                return
            end
            if entry.playing then return end
            if isPlaying and currentEntry ~= entry then
                -- пока парсился, стартовал другой трек — уступаем
                return
            end
            isPlaying = true; currentEntry = entry
            setEntryState(true)
            statusLabel.Text = string.format("▶ %s — %d events", tostring(track.name), #evs)
            task.spawn(function()
                local n = #evs
                local sorted = table.create(n)
                for i = 1, n do
                    local ev = evs[i]
                    sorted[i] = {t=math.max(tonumber(ev.t) or 0, 0), key=tostring(ev.key), state=tostring(ev.state), idx=i}
                end
                table.sort(sorted, function(a, b)
                    if a.t == b.t then return a.idx < b.idx end
                    return a.t < b.t
                end)
                local valid  = function() return isPlaying and currentEntry == entry end
                local vClock = 0.0
                local rLast  = os.clock()
                -- ПЕРЕМОТКА: публикуем состояние для полосы прогресса
                entry.seekReq   = nil
                playState.entry = entry
                playState.pos   = 0
                playState.dur   = sorted[n].t
                -- таблица зажатых клавиш: после прыжка их надо отпустить
                local held = {}
                local function releaseHeld()
                    for k in pairs(held) do
                        local ek = Enum.KeyCode[k]
                        if ek then pcall(emitKey, false, ek) end
                    end
                    held = {}
                end
                local function abandon()
                    releaseHeld()
                    if playState.entry == entry then playState.entry = nil end
                end
                local i = 1
                while i <= n do
                    local ev      = sorted[i]
                    local targetV = ev.t
                    while true do
                        if not valid() then abandon() return end
                        local now = os.clock()
                        vClock = vClock + (now - rLast) * SPEED
                        rLast  = now
                        playState.pos = vClock
                        if entry.seekReq then
                            local tgt = entry.seekReq
                            entry.seekReq = nil
                            releaseHeld()
                            local j = i
                            if tgt < ev.t then
                                while j > 1 and sorted[j - 1].t >= tgt do j = j - 1 end
                            else
                                while j <= n and sorted[j].t < tgt do j = j + 1 end
                            end
                            i, vClock, rLast = j, tgt, os.clock()
                            playState.pos = tgt
                            ev      = sorted[i]
                            targetV = ev and ev.t or tgt
                            statusLabel.Text = string.format(
                                "⏩ %s — %s / %s",
                                tostring(track.name), fmtDur(vClock), fmtDur(playState.dur))
                        end
                        if i > n then break end
                        if vClock >= targetV - 0.003 then break end
                        local remainR = (targetV - vClock) / SPEED
                        if remainR > 0.05 then
                            task.wait(math.min(remainR - 0.045, 0.05))
                        else
                            task.wait()
                        end
                    end
                    if i > n then break end
                    local enumKey = Enum.KeyCode[ev.key]
                    if enumKey then
                        if ev.state == "down" then
                            held[ev.key] = true
                        elseif ev.state == "up" then
                            held[ev.key] = nil
                        end
                        local ok = false
                        if ev.state == "down" then
                            ok = emitKey(true, enumKey)
                        elseif ev.state == "up" then
                            ok = emitKey(false, enumKey)
                        end
                        if not ok then
                            abandon()
                            entry.stopEntry("Input failed — use 'in:' button")
                            return
                        end
                    end
                    i = i + 1
                end
                abandon()
                entry.stopEntry("✓ Done — " .. tostring(track.name))
            end)
        end)
    end

    btn.MouseButton1Click:Connect(function()
        if entry.playing then entry.stopEntry("Stopped by user") else entry.startEntry() end
    end)

    star.MouseButton1Click:Connect(function()
        local k = trackKey(track)
        if likes[k] then likes[k] = nil else likes[k] = true end
        saveLikes()
        refreshStar()
        if onLikeToggled then onLikeToggled(track) end
    end)
    return entry
end

------------------------------------------------------------------
-- UTF-8 lower для кириллицы (string.lower в Luau трогает только ASCII,
-- поэтому «Гимн» не находился бы по запросу «гимн»)
------------------------------------------------------------------
local function utf8lower(s)
    local out = s:lower() -- ASCII уже здесь
    if not out:find("\208", 1, true) and not out:find("\209", 1, true) then return out end
    local buf = {}
    local i, n = 1, #out
    while i <= n do
        local b = out:byte(i)
        if b == 208 or b == 209 then
            local b2 = out:byte(i + 1) or 0
            -- А-П (D0 90-D0 9F) -> а-п (D0 B0-D0 BF); Р-Я (D0 A0-D0 AF) -> р-я (D1 80-D1 8F)
            if b == 208 and b2 >= 0x90 and b2 <= 0x9F then
                buf[#buf+1] = string.char(208); buf[#buf+1] = string.char(b2 + 0x20)
            elseif b == 208 and b2 >= 0xA0 and b2 <= 0xAF then
                buf[#buf+1] = string.char(209); buf[#buf+1] = string.char(b2 - 0x20)
            elseif b == 208 and b2 >= 0x80 and b2 <= 0x8F then
                -- Ђ..Џ, Ё, Є, Ї, І (U+0400-040F) -> ђ..џ (U+0450-045F)
                buf[#buf+1] = string.char(209); buf[#buf+1] = string.char(b2 + 0x10)
            else
                -- Ё/ё/украинские буквы и прочие двухбайтовые — копируем как есть
                buf[#buf+1] = string.char(b)
                if i < n then buf[#buf+1] = string.char(b2) end
            end
            i = i + 2
        else
            buf[#buf+1] = string.char(b)
            i = i + 1
        end
    end
    return table.concat(buf)
end

