-- нормализация удалённых песен репо (старт по первой ноте)
local function normalizeEvents(events)
    if type(events) ~= "table" or #events == 0 then return events end
    local minT = nil
    for i = 1, #events do
        local t = tonumber(events[i].t)
        if t and (minT == nil or t < minT) then minT = t end
    end
    if minT and minT > 0 then
        local shift = minT - START_AT
        for i = 1, #events do
            local t = tonumber(events[i].t)
            if t then events[i].t = t - shift end
        end
    end
    return events
end

-- индекс: все треки библиотеки
local LIB = {}
for _, t in ipairs(TRACKS) do
    table.insert(LIB, {name=t.name, artist=t.artist, cat=t.cat, bpm=t.bpm,
                       st=t.st, lvl=t.lvl, notes=t.notes, kind="notes"})
end

-- сколько треков сейчас в лайках (для чипа "★ Likes")
local function countLikes()
    local n = 0
    for _, t in ipairs(LIB) do
        if likes[trackKey(t)] then n = n + 1 end
    end
    return n
end

-- счётчики категорий + поисковый индекс (utf8-строчные для кириллицы)
local catCounts = {}
for _, t in ipairs(LIB) do
    catCounts[t.cat] = (catCounts[t.cat] or 0) + 1
    t.low = utf8lower(t.name .. " " .. (t.artist or ""))
end

local CAT_ORDER = {"Chaos","Phonk","Electronic","Game","Pop","Anime","Classical","Movie",
                   "Rock","Hip-Hop","K-Pop","FNF","Meme","Ringtone","Traditional",
                   "Vocaloid","Jazz","Other"}
local catsUi = {"All"}
for _, c in ipairs(CAT_ORDER) do
    if catCounts[c] then table.insert(catsUi, c) end
end
table.insert(catsUi, 2, "Likes")

-- чипы категорий
local activeCat = "All"
local chipRefs = {}
local refreshList  -- forward declaration: чипы вызывают refreshList по клику
local function makeChip(catName, order)
    local cnt = catName == "All" and #LIB
        or (catName == "Likes" and countLikes() or (catCounts[catName] or 0))
    local chip = Instance.new("TextButton")
    chip.Size = UDim2.new(0, catName == "All" and 44 or 74 + #catName * 2, 1, -6)
    chip.AutomaticSize = Enum.AutomaticSize.X
    chip.LayoutOrder = order
    chip.BackgroundColor3 = SURF2
    chip.Text = (catName == "Likes" and "★ " or "") .. catName .. " " .. cnt
    chip.Font = Enum.Font.GothamSemibold
    chip.TextSize = 10
    chip.TextColor3 = SUBTEXT
    if catName == "Chaos" then -- раздел хаоса выделен красным всегда
        chip.TextColor3 = Color3.fromRGB(255, 107, 107)
    elseif catName == "Likes" then -- раздел лайков выделен золотым
        chip.TextColor3 = AMBER
    end
    chip.BorderSizePixel = 0
    chip.Parent = catBar
    corner(chip, UDim.new(0, 6))
    local cp = Instance.new("UIPadding")
    cp.PaddingLeft = UDim.new(0, 8); cp.PaddingRight = UDim.new(0, 8); cp.Parent = chip
    chipRefs[catName] = chip
    chip.MouseButton1Click:Connect(function()
        activeCat = catName
        refreshList()
    end)
end

local function refreshChips()
    for name, chip in pairs(chipRefs) do
        if name == activeCat then
            chip.BackgroundColor3 = Color3.fromRGB(58, 110, 190)
            chip.TextColor3 = Color3.fromRGB(255, 255, 255)
        else
            chip.BackgroundColor3 = SURF2
            chip.TextColor3 = (name == "Chaos")
                and Color3.fromRGB(255, 107, 107)
                or (name == "Likes" and AMBER or SUBTEXT)
        end
        if name == "Likes" then
            chip.Text = "★ Likes " .. countLikes()
        end
    end
end

-- отфильтрованный индекс
local filtered = {}
local shown = 0
local RENDER_CHUNK = 40
local renderedEntries = {}

local function clearList()
    for _, e in ipairs(renderedEntries) do
        if e.playing then e.stopEntry() end
        e.row:Destroy()
    end
    renderedEntries = {}
    shown = 0
end

local function renderMore()
    local lim = math.min(shown + RENDER_CHUNK, #filtered)
    if lim <= shown then return end
    for k = shown + 1, lim do
        local track = filtered[k]
        local e = makeRow(k, track, k)
        table.insert(renderedEntries, e)
        shown = k
    end
    countLabel.Text = shown .. "/" .. #filtered
end

refreshList = function()
    clearList()
    local q = searchBox.Text
    q = q and utf8lower(q) or ""
    q = q:gsub("^%s+", ""):gsub("%s+$", "")
    filtered = {}
    for _, t in ipairs(LIB) do
        local inCat
        if activeCat == "All" then
            inCat = true
        elseif activeCat == "Likes" then
            inCat = likes[trackKey(t)] == true
        else
            inCat = (t.cat == activeCat)
        end
        if inCat and (q == "" or t.low:find(q, 1, true)) then
            table.insert(filtered, t)
        end
    end
    refreshChips()
    renderMore()
    -- сброс прокрутки в верх: новый фильтр всегда стартует с первой строки.
    -- (renderMore идемпотентен, поэтому сработавший CanvasPosition-сигнал
    -- лишней подгрузки не вызовет)
    listContainer.CanvasPosition = Vector2.new(0, 0)
    if #filtered == 0 then
        if activeCat == "Likes" then
            statusLabel.Text = "В Likes пусто — жми ★ рядом с песней"
        else
            statusLabel.Text = "Ничего не найдено: " .. searchBox.Text
        end
    else
        statusLabel.Text = string.format("Библиотека: %d треков", #filtered)
    end
end
-- клик по звезде: обновить все строки того же трека, чип и раздел
onLikeToggled = function(track)
    local k = trackKey(track)
    for _, e in ipairs(renderedEntries) do
        if trackKey(e.track) == k and e.refreshStar then e.refreshStar() end
    end
    local chip = chipRefs["Likes"]
    if chip then chip.Text = "★ Likes " .. countLikes() end
    if activeCat == "Likes" and likes[k] ~= true then
        refreshList() -- убрали из открытого раздела — строка исчезает
    end
end

-- подгрузка при скролле
listContainer:GetPropertyChangedSignal("CanvasPosition"):Connect(function()
    local pos = listContainer.CanvasPosition.Y
    local canvas = listContainer.AbsoluteCanvasSize.Y
    local view = listContainer.AbsoluteWindowSize.Y
    if pos + view >= canvas - 300 then
        if shown < #filtered then
            renderMore()
        end
    end
end)

-- поиск с debounce
local searchToken = 0
searchBox:GetPropertyChangedSignal("Text"):Connect(function()
    searchToken = searchToken + 1
    local my = searchToken
    local txt = searchBox.Text
    clearBtn.Visible = (#txt > 0)
    task.delay(0.15, function()
        if my == searchToken then refreshList() end
    end)
end)
clearBtn.MouseButton1Click:Connect(function()
    clearBtn.Visible = false
end)

-- инициализация категорий и списка
for i, c in ipairs(catsUi) do makeChip(c, i) end
refreshList()

------------------------------------------------------------------
-- Удаленные песни из репо (после встроенных; категория Repo)
------------------------------------------------------------------
task.spawn(function()
    local probeOk = false
    do
        local ok, raw = pcall(function() return game:HttpGet(BASE_URL .. "1.json") end)
        probeOk = ok and type(raw) == "string" and #raw > 2
    end
    if not probeOk then return end
    local added = 0
    for i = 1, TOTAL_TRACKS do
        local url = BASE_URL .. i .. ".json"
        local ok, raw = pcall(function() return game:HttpGet(url) end)
        if ok and raw then
            local jOk, data = pcall(function() return HttpService:JSONDecode(raw) end)
            if jOk and type(data) == "table" and type(data.events) == "table" then
                local evs = normalizeEvents(data.events)
                if type(evs) == "table" and #evs > 0 then
                    local lastT = 0
                    for _, e in ipairs(evs) do
                        local tt = tonumber(e.t) or 0
                        if tt > lastT then lastT = tt end
                    end
                    local rec = {name = tostring(data.name or ("Repo " .. i)),
                                 artist = tostring(data.author or "GitHub repo"),
                                 cat = "Repo", bpm = 120, st = math.ceil(lastT * 4),
                                 lvl = "Record", kind = "events", events = evs,
                                 low = (tostring(data.name or "") .. " " .. tostring(data.author or "")):lower()}
                    table.insert(LIB, rec)
                    added = added + 1
                end
            end
        end
        task.wait()
    end
    if added > 0 then
        catCounts["Repo"] = added
        table.insert(catsUi, "Repo")
        makeChip("Repo", #catsUi)
        refreshChips()
        if not isPlaying and shown >= #filtered then
            -- обновляем список, только если это безопасно (не рвём игру)
            refreshList()
        end
        statusLabel.Text = string.format("+%d треков из репо GitHub", added)
    end
end)

print(string.format(
    "[AutoPiano v6.7] %d встроенных треков | лайков: %d | input: %s | mode: %s | speed: %.2fx",
    #LIB, countLikes(), INPUT_NAME, INPUT_MODES[INPUT_MODE], SPEED))

------------------------------------------------------------------
-- АНТИ-СКРЫТИЕ, часть 4: мгновенная реакция на порчу GUI +
-- регистрация собранного окна в общем состоянии защиты.
------------------------------------------------------------------
AP.frame   = frame
AP.openBtn = openBtn
AP.cleanup = function()
    isPlaying    = false
    currentEntry = nil
end

gui.Destroying:Connect(function()
    -- последний шанс спасти инстанс (на части экзекуторов сработает)
    pcall(function() if gui.Parent == nil then gui.Parent = AP.home end end)
end)

gui.AncestryChanged:Connect(function(_, parent)
    if parent == nil then
        task.defer(function()
            if AP.gui == gui and gui.Parent == nil then
                local ok = pcall(function() gui.Parent = AP.home end)
                if not ok then pcall(buildGui) end -- уничтожен намертво
            end
        end)
    end
end)

gui:GetPropertyChangedSignal("Enabled"):Connect(function()
    if not gui.Enabled then gui.Enabled = true end -- сами мы Enabled не трогаем
end)

gui:GetPropertyChangedSignal("DisplayOrder"):Connect(function()
    if gui.DisplayOrder < 999999 then gui.DisplayOrder = 999999 end
end)

gui:GetPropertyChangedSignal("Name"):Connect(function()
    if gui.Name ~= "AutoPianoPlayer" then gui.Name = "AutoPianoPlayer" end
end)

end -- buildGui

buildGui()

------------------------------------------------------------------
-- АНТИ-СКРЫТИЕ, часть 5: СТОРОЖЕВОЙ ЦИКЛ.
-- Каждые 0.2с: GUI на месте? включён? поверх всех? не переименован?
-- Скрытое игрой — мгновенно возвращается, уничтоженное —
-- пересобирается с нуля. Цикл гаснет при повторном запуске скрипта
-- (смена поколения) или при закрытии Roblox.
------------------------------------------------------------------
local lastBuild = os.clock()
task.spawn(function()
    while genGet() == MY_GEN do
        task.wait(0.2)
        local g = AP.gui
        if g and g.Parent ~= nil then
            if not g.Enabled then pcall(function() g.Enabled = true end) end
            if g.DisplayOrder < 999999 then pcall(function() g.DisplayOrder = 999999 end) end
            if g.Name ~= "AutoPianoPlayer" then pcall(function() g.Name = "AutoPianoPlayer" end) end
            -- игру спрятали окно или кнопку — возвращаем (если не юзер закрыл)
            if AP.frame and not AP.userClosed and not AP.frame.Visible then
                pcall(function() AP.frame.Visible = true; AP.openBtn.Visible = false end)
            end
            if AP.openBtn and AP.userClosed and not AP.openBtn.Visible then
                pcall(function() AP.openBtn.Visible = true end)
            end
        elseif g then
            -- GUI сняли с дерева: пробуем вернуть, не получилось — пересобираем
            if AP.cleanup then pcall(AP.cleanup) end
            local ok = pcall(function() g.Parent = AP.home end)
            if (not ok) and (os.clock() - lastBuild) > 2 then
                lastBuild = os.clock()
                pcall(buildGui)
                print("[AutoPiano] GUI был уничтожен — пересобран заново")
            end
        end
    end
end)
